import resultsRaw from '../data/results.json'
import type { Family } from '../types'

// ===========================================================================
// Benchmarks data — base-vs-best metrics for the Benchmarks view.
//
// Generated by scripts/build-benchmarks.mjs from extras/results/INDEX.json
// (regenerate with `npm run build:benchmarks`). Mirrors lib/data.ts: a typed
// import of bundled JSON + a few helpers. The view must render even when
// `best` is null (no finetuned run promoted yet) and when idOod is empty.
// ===========================================================================

export interface NextStepMetrics {
  top1: number
  top3: number
  top5: number
  mrr: number
}

export interface CompletionMetrics {
  exactMatch: number
  normEditDist: number
  tokenAcc: number
  blockAcc: number
}

export interface Confusion {
  tp: number
  fp: number
  tn: number
  fn: number
}

export interface AnomalyMetrics {
  binAcc: number
  precision: number
  recall: number
  f1: number
  rocAuc: number
  ruleAttrAcc: number
  confusion: Confusion
}

/** A full model entry (all three tasks). nextstep/completion/anomaly may be null per task. */
export interface ModelMetrics {
  label: string
  modelRef: string
  nextstep: NextStepMetrics | null
  completion: CompletionMetrics | null
  anomaly: AnomalyMetrics | null
}

/** nextstep + completion for a single family slice (per-family + ID/OOD views). */
export interface FamilyTasks {
  nextstep: NextStepMetrics | null
  completion: CompletionMetrics | null
}

export interface PerFamilyRow {
  family: Family | string
  base: FamilyTasks | null
  best: FamilyTasks | null
}

export interface IdOodRow {
  family: Family | string
  /** "told the rules" — the in-distribution (all-family) run on this family's slice. */
  id: FamilyTasks
  /** "learned the rules" — the leave-one-family-out run, held out on this family. */
  ood: FamilyTasks
}

/** One data-scaling point: a run trained on `size` sequences and its overall accuracy. */
export interface ScalingPoint {
  /** Number of training sequences (from the `data-size:<N>` tag). */
  size: number
  /** Next-step Top-1 accuracy (overall), or null if the task is absent. */
  nextstepTop1: number | null
  /** Completion block-accuracy (overall), or null if the task is absent. */
  completionBlockAcc: number | null
}

export interface Benchmarks {
  base: ModelMetrics | null
  best: ModelMetrics | null
  oracle: { anomaly: AnomalyMetrics | null } | null
  perFamily: PerFamilyRow[]
  idOod: IdOodRow[]
  /** Accuracy vs #training sequences, ascending by size. Empty until scaling runs are promoted. */
  scaling: ScalingPoint[]
  generatedAt: string | null
}

export const benchmarks = resultsRaw as unknown as Benchmarks

/** Typed data-scaling series (ascending by size; empty until promoted). */
export const scaling: ScalingPoint[] = benchmarks.scaling ?? []

/** delta = best − base, or null if either side is missing. */
export function delta(best: number | null | undefined, base: number | null | undefined): number | null {
  if (best == null || base == null) return null
  return best - base
}

/** Format a 0..1 metric as a percentage string (e.g. 0.69 → "69.0%"). */
export function pct(x: number | null | undefined, digits = 1): string {
  if (x == null) return '—'
  return `${(x * 100).toFixed(digits)}%`
}

/** Format a raw 0..1 metric (NED, MRR, ROC-AUC) without a percent sign. */
export function num(x: number | null | undefined, digits = 3): string {
  if (x == null) return '—'
  return x.toFixed(digits)
}

/** Signed percentage delta, e.g. +12.3pp / −0.4pp. */
export function deltaPct(d: number | null, digits = 1): string {
  if (d == null) return '—'
  const sign = d >= 0 ? '+' : '−'
  return `${sign}${(Math.abs(d) * 100).toFixed(digits)}pp`
}

/** Signed raw delta, e.g. +0.123 / −0.004. */
export function deltaNum(d: number | null, digits = 3): string {
  if (d == null) return '—'
  const sign = d >= 0 ? '+' : '−'
  return `${sign}${Math.abs(d).toFixed(digits)}`
}
